async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics', { cache: 'no-store' }).then((r) => r.json()),
      fetch('/api/notifications', { cache: 'no-store' }).then((r) => r.json()),
      fetch('/api/settings', { cache: 'no-store' }).then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 0, visitors: 0, bounceRate: 0 },
      notifications: [],
      settings: { theme: 'system', notifications: true },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Visitors: {analytics.visitors}</p>
        <p>Bounce rate: {analytics.bounceRate}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No new notifications</p>
        ) : (
          <ul>
            {notifications.map((notification: { id: string | number; message: string }) => (
              <li key={notification.id}>{notification.message}</li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications enabled: {settings.notifications ? 'Yes' : 'No'}</p>
      </section>
    </div>
  )
}

